                  '**当前读的锁**：`FOR UPDATE` 加 `X` 锁（排他）；`LOCK IN SHARE MODE` 加 `S` 锁（共享）；`UPDATE`/`DELETE` 加 `X` 锁',
                  '**幻读的分界**：**快照读靠 MVCC 挡住新行**；**当前读必须看到新行，所以只能靠间隙锁阻止插入**',
