                questionId: 'java-06-Q50',
                intent:
                  '核心是「所有读都加共享锁」，由此推出性能退化，并说明「为什么几乎不用但不该说它没用」。',
                points: [
                  '**实现方式**：**所有普通 `SELECT` 都会隐式转成 `SELECT ... LOCK IN SHARE MODE`**（加共享锁）',
                  '**后果**：读读可并发（共享锁兼容），但**读写互斥、写写互斥** → 并发度退化到接近串行',
                  '**自动提交必须关闭**：SERIALIZABLE 下若 `autocommit=1`，每条语句自成事务，锁立刻释放，几乎等于 RC',
                  '**幻读**：被完全阻止（因为读也加锁，别的事务无法插入到「读过的区间」）',
                  '**死锁风险**：共享锁升级为排他锁时（先读后写）容易死锁，需要应用层重试',
                  '**实际使用**：生产几乎不用；**适合「一致性要求极高 + 并发极低」**的场景（如财务结算、批处理对账）',
                  '**替代方案**：用 `FOR UPDATE` 只对关键语句加锁（比整库串行化精确得多），或用应用层分布式锁',
                  '**注意**：InnoDB 在 SERIALIZABLE 下**不会真的串行执行**，只是加锁更严格——「串行化」是「效果等价于串行」，不是「物理串行」',
                ],
                depth:
                  '「SERIALIZABLE 和『单线程处理』有什么区别」——**并发度不同**。单线程是「同一时刻只有一个操作」，吞吐受限于单核；SERIALIZABLE 是「读读可以并发」（共享锁兼容），所以「只读负载」下仍有并发能力，只是**任何写都会阻塞所有读该行的操作**。**所以在「读多写极少」的极端场景（如配置表、字典表），SERIALIZABLE 并不一定慢**——这个细节能纠正「串行化=一定最慢」的刻板印象。**判断标准还是「读写比例」**，而不是级别高低。',
                followup:
                  '「什么场景真的会用到 SERIALIZABLE」——三个：① **财务/账务的日终对账**（要求绝对一致，且本来就是批处理、可接受慢）；② **数据修复脚本**（跑一次、要求不出错，性能无所谓）；③ **替代方案缺失时的兜底**（如某些 ORM 框架无法精确控制锁）。**注意：即使是这些场景，更常见的做法也是「加 `FOR UPDATE` 或停写维护」，而不是全局切 SERIALIZABLE**——因为隔离级别是「会话/全局」设置，太粗，影响面不可控。',
