                kind: 'question',
                title: 'RR 下事务 A 已提交的数据，事务 B 能看见吗？',
                questionId: 'java-06-Q51',
                intent:
                  '考「时机」这个细节。答案取决于「B 的 ReadView 何时生成」，不是简单的「能/不能」。',
                points: [
                  '**取决于 B 的 ReadView 生成时机**，而不是「A 是否提交」',
                  '**若 B 的首次快照读发生在 A 提交之后** → **能看见**（A 的 `trx_id < B 的 min_trx_id`）',
                  '**若 B 的首次快照读发生在 A 提交之前** → **看不见**（A 的 `trx_id` 在 B 的 `m_ids` 中，不可见）',
                  '**注意「B 已 `BEGIN`」不等于「B 已生成 ReadView」**——`BEGIN` 不生成快照，首次 `SELECT` 才生成',
                  '**当前读例外**：B 用 `SELECT ... FOR UPDATE` 或 `UPDATE` → **一定能看见**（读最新版本）',
                  '**RC 下**：B 每次 `SELECT` 新建 ReadView → **只要 A 已提交就能看见**',
                  '**经典误答**：「RR 下 B 永远看不到 A 在 B 开始后提交的数据」——这个说法忽略了「ReadView 惰性生成」这个时机',
                  '**实践含义**：这就是「RR 快照是『首次读那一刻』的状态」，而不是「事务开始那一刻」',
                ],
                depth:
                  '这道题的价值在于「破除一个背诵式结论」。很多人背「RR 可重复读 = 事务开始时拍快照」，然后斩钉截铁答「看不见」——**但实际答案要看时序**。**标准回答应该先反问「B 的第一次读发生在什么时候」**，然后分情况说。**这类「先澄清前提再回答」的能力，是面试里最稀缺的**——它说明你不是在套模板，而是在按机制推理。同样的思路也适用于「`@Transactional` 里能不能读到别的线程刚提交的数据」「缓存与数据库谁先更新」等一堆「答案取决于时序」的问题。',
