                  '「行锁锁的是索引项」这句话值得展开：InnoDB 实现行锁的方式是「在索引记录上加锁标记」，所以**锁的粒度取决于索引**。这带来三个推论：**① 同一行可能有多个索引，不同事务可能通过不同索引锁同一行**（表现为「看起来无关却互相阻塞」）；**② 二级索引查询要「锁二级索引 + 回表锁聚簇索引」，是两把锁**；**③ 更新主键等于「删除 + 插入」**，会锁更多东西。**理解这一点，就能解释一大批「诡异阻塞」**：为什么改 A 行却阻塞了 B 行（因为它们在同一个间隙里）、为什么加了索引反而更容易死锁（锁更精确但涉及两棵树）。',
