                  '「看起来无关却互相阻塞」的经典场景值得讲：表有 `id` 主键和 `age` 普通索引。事务 A `UPDATE ... WHERE id BETWEEN 10 AND 20`（锁 (5,20] 的临键锁）；事务 B `INSERT id = 25`——**看起来不相干**，但如果 A 的范围扫描到 id=25 才发现不满足（因为数据只到 25），**A 会锁住 id=25 这个记录**，B 的插入就阻塞了。**这个「扫描到边界外一行」的规则是 InnoDB 的真实行为**，也是「范围更新要小心」的物理依据。**回答里能举出这个例子，说明真的分析过锁**。',
