                  '**必须在事务内使用**：`autocommit=1` 时语句结束就释放锁，等于没用',
                  '**会阻塞**：别的事务的 `FOR UPDATE` / `UPDATE` / `DELETE` 同范围操作；普通 `SELECT`（快照读）**不阻塞**',
                  '**`LOCK IN SHARE MODE`（8.0 的 `FOR SHARE`）**：当前读 + S 锁，多个可共存，但与 X 互斥',
                  '**悲观锁**：假定冲突必然发生，先加锁再操作（`FOR UPDATE`）；**保证强一致，但并发度低**',
                  '**乐观锁**：假定冲突少，不加锁，提交时校验版本号（`WHERE version = ?`）；**并发高，但需重试**',
