                  '**行锁**：锁索引记录，**开销大（要维护锁结构）、并发度高**；InnoDB 支持',
                  '**选择原则**：**并发写入多 → 行锁；只读或批量操作 → 表锁**（一次锁完比逐行锁快）',
                  '**InnoDB 的默认是行锁**，但**「没走索引」会退化成表级效果**（锁所有扫描行 + 间隙）',
                  '**表锁的两种模式**：读锁（`LOCK TABLES ... READ`，共享）、写锁（`WRITE`，独占）',
