                  '**偶发慢的四个常见原因**：① 等锁（`innodb_lock_wait_timeout`）② 刷脏页（脏页比例高）③ redo log 切换（`checkpoint`）④ 其他大查询抢资源',
                  '**一直慢的排查链**：慢查询日志定位 → `EXPLAIN` 看 `type/key/rows/Extra` → 归因三类（没走索引 / 走错索引 / 走太多行）',
                  '**没走索引的信号**：`type=ALL`、`key=NULL`；常见原因是函数、隐式转换、前导模糊、违反最左前缀',
