                  '**走太多行的信号**：索引正常但业务需要扫很多行 → 深分页、大范围、实时聚合 → 改架构（游标、预聚合、缓存）',
                  '**终极工具**：`EXPLAIN ANALYZE`（8.0.18+）看实际执行；`SHOW PROFILE` / `performance_schema` 看各阶段耗时；`optimizer_trace` 看优化器决策过程',
                  '**回答结构**：先分类 → 再定位 → 再看计划 → 再归因 → 再施策 → 最后回归验证',
