                  '**阈值**：`long_query_time=1`（秒，可带小数如 `0.5`）；**注意只记录超过阈值的**',
                  '**`log_queries_not_using_indexes`**：记录未使用索引的查询——**慎开**（小表也走全表，日志会爆），建议配 `log_throttle_queries_not_using_indexes`',
                  '**`min_examined_row_limit`**：只记录「扫描行数超过 N」的查询，过滤掉小表噪音',
