                depth:
                  '「为什么先写旧库再写新库」这个细节值得解释：若先写新库成功、写旧库失败，那「旧库仍是权威数据源」（因为读还走旧库），此时数据不一致且旧库缺数据 → **用户看到的是「写入失败但实际新库有」**，后续切回新库时会出现「幽灵数据」。**而先写旧库成功、写新库失败，则「权威数据源正确」，只需重试补写新库**——风险可控。**这个「以当前权威源为准」的原则，在所有「迁移/双写」场景都适用**（如「缓存与数据库双写」也是同样的道理：先写库再删缓存）。',
