                      '很多人以为「6.0 之前 Redis 是纯单线程」，其实**4.0 起就有 BIO 后台线程**，负责三类会阻塞的工作：**`close_file`**（关闭大文件，如 AOF/RDB）、**`aof_fsync`**（AOF 的 `fsync` 落盘，`everysec` 策略就是交给后台线程做的）、**`lazy_free`**（4.0 引入的异步释放，`UNLINK` 就是走这个）。此外还有 `serverCron`（定时任务，负责过期抽样、渐进式 rehash 的搬迁等）。**所以准确表述是：Redis 用「多线程做 IO 与释放」+「单线程做命令执行」的混合模型，把「必须串行」的部分收窄到了最小。**',
