                    detail:
                      '既然命令串行，**任何一条慢命令都会拖住所有人**。四个来源：**第一，O(N) 命令**——`KEYS *`（遍历全库）、`FLUSHALL`、`HGETALL`（大 Hash）、`SMEMBERS`（大 Set）、`LRANGE key 0 -1`（大 List）、`ZRANGE key 0 -1`；**第二，大 key 的删除**——`DEL` 一个百万元素的 Set 是 O(N) 且同步释放内存，主线程会卡住数秒，必须用 `UNLINK`（异步释放）；**第三，`fork` 阻塞**——`BGSAVE` / AOF 重写要 `fork`，`fork` 本身耗时与内存页表大小成正比，**内存 10GB 的实例 `fork` 可能阻塞几十到几百毫秒**；**第四，AOF 刷盘**——`appendfsync always` 每条命令都同步落盘，吞吐直接掉到几千 QPS；`everysec` 在磁盘抖动时可能出现「fsync 阻塞主线程」导致延迟毛刺（`aof_delayed_fsync` 指标可观测）。',
