                  caption:
                    '**两个值得展开的点**：**第一，`list-max-listpack-size -2`（8KB）这个默认值是精心选的**——太小则节点多、指针开销大（退化成链表）；太大则单节点 `memmove` 代价高、且「修改一个元素要复制整块」（COW 场景下更糟）。**8KB 大致等于 2 个内存页**，既保证局部性又限制单次拷贝量。**第二，`intset` 的「升级不可逆」是个真实的内存陷阱**：曾经有人往 Set 里写了一个时间戳（毫秒级，超过 int32），导致整个 Set 从 16 位升到 64 位，**内存直接翻 4 倍**，即使后来删掉时间戳也不降级——只能 `DEL` 重建。**这正是「Set 里不要混放大整数」这条规范的技术依据。**',
