                  '**头节点 32 层**（`ZSKIPLIST_MAXLEVEL = 32`），不存数据，是查找入口',
                  '**层高生成**：`while (random() < 0.25) level++`，**每升一层概率 1/4**（`ZSKIPLIST_P = 0.25`）',
                  '**期望层高**：`1/(1-p) = 1.33` 层；最高层约 `log₄N`',
                  '**查找**：从最高层向右走，比目标大就下降一层；**每层平均 4 步**，总步数 ≈ `2·log₂N`',
