                  '**B+ 树在内存的优势消失**：多叉减少比较次数，但**节点内二分 + 插入 `memmove`** 反而更复杂、内存有碎片',
                  '**MySQL 用 B+ 树是因为磁盘按页 IO**：扇出 1170、3 层存 2000 万行 → **3 次 IO**；跳表 `log₄N ≈ 12` 层 → 最坏 12 次随机 IO',
