                depth:
                  '**「为什么「层数」在磁盘上是致命的」要说透**：磁盘的读取单位是页（4KB/16KB），**B+ 树一个节点就是一页**，一次 IO 拿到几百个 key 在页内二分，**局部性极好**；跳表的每个节点是独立分配的内存块，**在磁盘上就落在不同页上**，每跳一层都可能是一次随机 IO。机械盘随机 IO 约 10ms，`12 × 10ms = 120ms`，完全不可接受；B+ 树 3 次 IO 约 30ms（且根与中间层常驻 Buffer Pool，实际 1 次）。**这个对比的普适结论是：数据结构的选择取决于存储介质的「最小访问单位」与「随机访问代价」**——内存里随机访问与顺序访问的差距是几倍，磁盘上是几万倍。**能把这句总结说出来，这道题就答到了根上。**',
