                caption:
                  '**一个必须知道的「兜底开关」**：`stop-writes-on-bgsave-error yes`（默认）——**当 RDB 最近一次保存失败时，Redis 拒绝所有写命令**。**好处**：防止「用户以为数据持久化了，其实一直在失败」。**坏处**：一次磁盘抖动就可能导致业务整体不可写（很多线上事故是这个开关触发的）。**所以生产上要么保证磁盘可靠 + 监控告警，要么明确评估后关掉它并接受「持久化失败但继续服务」**。**这类「默认值是安全优先」的开关在 Redis 里不少（还有 `protected-mode`、`requirepass` 的空值），理解「默认值的立场」本身就是运维素养。**',
