                depth:
                  '**「为什么不能只开 AOF」的完整理由**：**① 恢复慢**——200GB 的 AOF 重放可能几十分钟，期间服务不可用；**② 文件大**——AOF 通常是 RDB 的 2~5 倍，磁盘与网络传输成本高；**③ 单点损坏风险**——AOF 是文本追加，一旦中间损坏（磁盘坏块、误写），`redis-check-aof --fix` 只能截断，可能丢掉大段数据。**而 RDB 是「一次性写入 + 原子替换」**，文件要么完整要么不存在，**天然没有「中间损坏」问题**。**所以最优组合是「AOF（混合）保证实时性 + RDB 保证可恢复性」**——两个独立的文件，互为备份。**这个「两种机制互补而非互斥」的思路，与「MySQL 的 redo log + 全量备份」完全同构。**',
