                  '**`bgsave`**：**`fork` 子进程写临时文件**，主线程继续服务；**只在 fork 那一刻阻塞**',
                  '**原子替换**：子进程写完 → 主线程 `rename` 临时文件为 `dump.rdb`（保证任何时刻文件完整）',
