                  '**投票**：向其他哨兵请求投票；**同一 `epoch` 内每个哨兵只投一票**（先到先得）',
                  '**当选**：拿到 **`majority`（哨兵总数/2+1）票**；一轮无结果则 `epoch++` 重来',
                  '**`epoch` 大者优先**：防止旧轮次的票被复用（类似 Raft 的 term）',
                  '**选新主三级**：`replica-priority` 小 → `offset` 大（数据最新）→ `runid` 小（结果确定）',
