                  '**hash tag**：`{user100}.profile` 与 `{user100}.orders` **只用 `{}` 内内容算槽** → 落在同一槽',
                  '**注意**：`{}` 内为空（`{}`）或没有 `{}` 时，**整串参与计算**',
