                  '**倾斜成因二：热点 key** → key 拆分（`key:{1..N}`）+ 客户端聚合 / 本地缓存',
                  '**倾斜成因三：hash tag 滥用** → 减少 tag 粒度，别把大量 key 绑一个 tag',
