                points: [
                  '**定义**：**单个热点 key 过期瞬间**，大量并发请求同时 miss → 一起回源 → 数据库被打爆',
                  '**与穿透的区别**：击穿的数据**存在**（只是缓存刚失效）；穿透的数据**根本不存在**',
                  '**互斥锁**：`SETNX` 抢锁，只有抢到的线程重建，其他等待/降级；**保一致性、牺牲可用性**',
                  '**逻辑过期**：value 里带 `expireAt`，过期后**返回旧值 + 异步重建**；**保可用性、牺牲一致性**',
                  '**第三条路**：**永不过期 + 后台定时刷新**（热点明确、变更可控时最省心）',
                  '**选型判据**：能不能接受旧值（价格/库存→互斥锁；商品详情→逻辑过期）+ 重建耗时（慢→逻辑过期）',
                ],
                depth:
                  '**「互斥锁的两个隐藏坑」**：**① 锁提前失效**——如果重建时间超过锁的 TTL（如设 3 秒，但查库 + 聚合花了 5 秒），**锁会自动释放，第二个线程进来也去重建**，此时需要用「看门狗续期」（Redisson 的做法）或把 TTL 设得足够长；**② 未抢到锁的线程怎么办**——「sleep 重试」会占线程（高并发下线程池被占满），**更好的做法是「短暂等待后返回降级内容」或「直接返回旧值（如果缓存里还有）」**。**这两个坑在实际项目里都很难调，能说出来说明你真写过。**',
                followup:
                  '「逻辑过期怎么实现才不重复重建」——**用一把「重建锁」（`SETNX` 短 TTL）**：谁抢到谁去异步重建，**其余线程直接返回旧值不等**。**注意「重建失败」的处理**：如果重建线程查库失败，**不要删除旧值**（否则下次请求会 miss 并再次触发重建，形成雪崩），**应该保留旧值并记录告警**，等下次再试。**这个「保留旧值」的细节是逻辑过期的关键**——它的设计哲学是「宁可给旧值，也不给空」。',
