                  '**先更后删的剩余风险**：读线程「更新库前读库（旧值）+ 删缓存后回填」——**要求「读+回填」慢于「写库+删缓存」，概率极低**',
                  '**为什么删而不是更新 ①**：写多读少时「更新缓存」是**无效写**，删除是懒加载',
                  '**为什么删而不是更新 ②**：并发下「更新缓存」会**旧值覆盖新值**（调度顺序与库不一致）',
