                depth:
                  '**「`ratio < 1` 为什么更危险」是一个很好的追问**：**它说明 `used_memory_rss` 小于 `used_memory`**，**即「Redis 认为自己在用的内存，有一部分已经被换出到 swap 了」**——**这意味着「访问那部分数据会触发缺页中断，从磁盘读回」，延迟从微秒级涨到毫秒级**。**所以「`ratio` 小于 1 时不要高兴（以为省内存），而要立刻查 swap」**。**这个「指标读法的反直觉之处」，能说出来说明你真看过监控。**',
                followup:
                  '「`activedefrag` 有什么代价」——**CPU**（**内存整理要移动数据，是 CPU 密集型**）；**可能影响延迟**（**整理时占用主线程时间片**）。**所以它有「水位控制」**：**`active-defrag-threshold-lower`（碎片率达到多少才开始整理，默认 10%）**、**`upper`（达到多少就全力整理，默认 100%）**、**`active-defrag-cycle-min/max`（占用 CPU 的比例上下限，默认 1%~25%）**。**实践**：**低峰期开、高峰期关**（**或者接受「重启一次」这个更彻底的办法**）。',
